  CheckBuy(): boolean {

    return GResponse.MyCourseIds.find(n =>
      n == this.selectedCourseId) || this.course.price == 0 ? true : false;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onClick(id: number | string) {

    this.router
      .navigate(
        ['/Home', 'Search'],
        {
          queryParams:
          {
            categoryIds: [id],
            page: 1
          }
        });
  }

  goNextPage() {

    if (this.filteredCourses.endPage == null) {
      return;
    }
    if (this.filteredCourses.pageId < this.filteredCourses.endPage) {
      this.setQueryParams(+this.filteredCourses.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= +pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  setQueryParams(pageId: number) {

    SharedIonic.loading(this.loadingController);

    const page = pageId < 1 ? 1 : pageId;

    const filter = new CourseFilterModel
      (false, page, this.filteredCourses.takeEntity, this.courseSearch, this.filteredCourses.sortId);

    this.filteredCourses = filter;

    this.content.scrollToTop(1500);

    this.courseService.GetCoursesByFilter(filter).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.filteredCourses = res.data;
          this.notfound = false;

        } else if (res.status === GResponse.NotFoundStatus) {

          this.notfound = true;
          SharedIonic.toast(this.toastController, 'موردی یافت نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  onSelectItem(model: ICourseModel) {

    this.selectedCourseId = +model.id;
    this.course = model;
  }
